"""Deterministic index-options radar and re-entry governor.

This module is advisory only. It never places broker orders and never fills
missing market evidence with inferred values. Long-premium candidates lock for
paper execution at the configured score floor once core quote/contract safety
is valid; directional confirmation gates remain auditable warnings. Defined-
risk premium selling keeps its stricter structural risk gates.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any

from .index_options_seller import SELLER_MIN_SCORE


INDEX_CONFIG: tuple[dict[str, str], ...] = (
    {"key": "NIFTY", "label": "NIFTY 50", "bucket": "BROAD", "exchange": "NSE"},
    {"key": "SENSEX", "label": "SENSEX", "bucket": "BROAD", "exchange": "BSE"},
    {"key": "BANKNIFTY", "label": "NIFTY BANK", "bucket": "FINANCIAL", "exchange": "NSE"},
    {"key": "FINNIFTY", "label": "NIFTY FIN SERVICE", "bucket": "FINANCIAL", "exchange": "NSE"},
)

MIN_DAILY_ENTRIES = 0
MAX_DAILY_ENTRIES = 20
MAX_ATTEMPTS_PER_INDEX = 20
MAX_CONCURRENT_TRADES = 2
MIN_ELIGIBLE_SCORE = 70.0

_LONG_PREMIUM_SAFETY_GATES = ("fresh", "contractEconomics")


def _num(value: Any) -> float | None:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if number == number else None


def _iso(value: Any) -> datetime | None:
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)


@dataclass
class IndexOptionReEntryGovernor:
    """Durable daily attempt/exit facts used by the options session engine."""

    trade_counts: dict[str, int] = field(default_factory=dict)
    sl_counts: dict[str, int] = field(default_factory=dict)
    last_exits: dict[str, dict[str, Any]] = field(default_factory=dict)

    def record_entry(self, instrument: str) -> None:
        key = instrument.upper().strip()
        self.trade_counts[key] = self.trade_counts.get(key, 0) + 1

    def record_exit(
        self,
        instrument: str,
        exit_reason: str,
        direction: str,
        exit_time: datetime,
        exit_price: float,
    ) -> None:
        key = instrument.upper().strip()
        reason = exit_reason.upper().strip()
        self.last_exits[key] = {
            "time": exit_time.isoformat(),
            "reason": reason,
            "direction": direction.upper().strip(),
            "price": exit_price,
        }
        if reason == "STOP_LOSS":
            self.sl_counts[key] = self.sl_counts.get(key, 0) + 1


def can_reenter_index_option(
    instrument: str,
    candidate_direction: str,
    current_time: datetime,
    governor: IndexOptionReEntryGovernor,
    *,
    fresh_breakout_confirmed: bool = False,
    oi_aligned: bool = False,
    breadth_aligned: bool = False,
    opposite_confirmation: bool = False,
) -> dict[str, Any]:
    """Evaluate one index/side re-entry with auditable rejection reasons."""
    key = instrument.upper().strip()
    direction = candidate_direction.upper().strip()
    attempts = governor.trade_counts.get(key, 0)
    daily_entries = sum(max(0, int(value)) for value in governor.trade_counts.values())
    stops = governor.sl_counts.get(key, 0)
    base = {"allowed": False, "instrument": key, "attempts": attempts, "dailyEntries": daily_entries,
            "dailyEntryCap": MAX_DAILY_ENTRIES, "slHits": stops}
    if not key or direction not in {"CALL", "PUT", "BULLISH", "BEARISH", "NEUTRAL"}:
        return {**base, "reason": "INVALID_INSTRUMENT_OR_DIRECTION"}
    if daily_entries >= MAX_DAILY_ENTRIES:
        return {**base, "reason": "MAX_DAILY_ENTRIES_REACHED"}
    if attempts >= MAX_ATTEMPTS_PER_INDEX:
        return {**base, "reason": "MAX_INDEX_ATTEMPTS_REACHED"}
    if stops >= 2:
        return {**base, "reason": "HARD_BAN_TWO_SL_HITS"}
    prior = governor.last_exits.get(key)
    if not prior:
        return {**base, "allowed": True, "reason": "FRESH_INSTRUMENT"}

    exited_at = _iso(prior.get("time"))
    if exited_at is None:
        return {**base, "reason": "EXIT_TIMESTAMP_MISSING"}
    now = current_time if current_time.tzinfo else current_time.replace(tzinfo=timezone.utc)
    elapsed = max(0.0, (now - exited_at.astimezone(now.tzinfo)).total_seconds() / 60.0)
    reason = str(prior.get("reason") or "").upper()
    prior_direction = str(prior.get("direction") or "").upper()

    if reason in {"TARGET", "TRAILING_SL_PROFIT"}:
        cooldown = 20.0 if reason == "TARGET" else 30.0
        if elapsed < cooldown:
            return {**base, "reason": "PROFIT_COOLDOWN_ACTIVE", "cooldownRemainingMin": round(cooldown - elapsed, 1)}
        if not (fresh_breakout_confirmed and oi_aligned and breadth_aligned):
            return {**base, "reason": "TREND_RESUMPTION_NOT_CONFIRMED"}
        return {**base, "allowed": True, "reason": "PROFIT_REENTRY_CONFIRMED", "riskScale": 0.5}

    if reason == "STOP_LOSS":
        if direction == prior_direction:
            if elapsed < 45.0:
                return {**base, "reason": "SL_SAME_DIRECTION_COOLDOWN", "cooldownRemainingMin": round(45.0 - elapsed, 1)}
            if not (fresh_breakout_confirmed and oi_aligned and breadth_aligned):
                return {**base, "reason": "SL_RECLAIM_NOT_CONFIRMED"}
            return {**base, "allowed": True, "reason": "SL_RECLAIM_CONFIRMED", "riskScale": 0.5}
        if not (opposite_confirmation and oi_aligned and breadth_aligned):
            return {**base, "reason": "REVERSAL_MISSING_CONFIRMATION"}
        return {**base, "allowed": True, "reason": "REVERSAL_CONFIRMED", "riskScale": 0.5}

    return {**base, "reason": "EXIT_STATE_NOT_ELIGIBLE"}


def _macro_lookup(snapshot: dict[str, Any], label: str) -> dict[str, Any]:
    rows = ((snapshot.get("macroDataStrip") or {}).get("morning") or [])
    wanted = label.upper()
    for row in rows:
        if str(row.get("label") or row.get("name") or "").upper() == wanted:
            return row
    return {}


def _candidate(index: dict[str, str], snapshot: dict[str, Any]) -> dict[str, Any]:
    supplied = ((snapshot.get("indexOptions") or {}).get("indices") or {}).get(index["key"], {})
    macro = _macro_lookup(snapshot, index["label"])
    spot = _num(supplied.get("spot") if supplied else macro.get("val"))
    components = supplied.get("scores") if isinstance(supplied.get("scores"), dict) else {}
    required_scores = ("trend", "breakout", "futuresOi", "optionChain", "breadth", "contract", "regime")
    weights = {"trend": 20, "breakout": 15, "futuresOi": 15, "optionChain": 15, "breadth": 20, "contract": 10, "regime": 5}
    missing = [name for name in required_scores if _num(components.get(name)) is None]
    score = None
    if not missing:
        score = round(sum((_num(components[name]) or 0.0) * weights[name] / 100.0 for name in required_scores), 2)

    gates = supplied.get("gates") if isinstance(supplied.get("gates"), dict) else {}
    required_gates = ("fresh", "structure", "breakout", "futuresOi", "optionChain", "breadth", "contractEconomics", "riskReward")
    failed = [name for name in required_gates if gates.get(name) is False]
    unavailable = [name for name in required_gates if gates.get(name) is not True and name not in failed]
    safety_failed = [name for name in _LONG_PREMIUM_SAFETY_GATES if gates.get(name) is False]
    safety_unavailable = [name for name in _LONG_PREMIUM_SAFETY_GATES if gates.get(name) is not True and name not in safety_failed]

    direction = str(supplied.get("direction") or "").upper()
    contract = supplied.get("contract") if isinstance(supplied.get("contract"), dict) else {}
    premium = _num(contract.get("ltp"))
    contract_executable = bool(str(contract.get("symbol") or "").strip() and premium is not None and premium > 0)

    eligible = bool(
        direction in {"CALL", "PUT"}
        and score is not None
        and score >= MIN_ELIGIBLE_SCORE
        and not safety_failed
        and not safety_unavailable
        and contract_executable
    )

    if missing:
        state, reason = "NO_TRADE", f"DATA_INCOMPLETE:{','.join(sorted(set(missing)))}"
    elif safety_failed:
        state, reason = "NO_TRADE", f"SAFETY_GATE_FAILED:{','.join(safety_failed)}"
    elif safety_unavailable:
        state, reason = "NO_TRADE", f"SAFETY_DATA_INCOMPLETE:{','.join(safety_unavailable)}"
    elif not contract_executable:
        state, reason = "NO_TRADE", "CONTRACT_NOT_EXECUTABLE"
    elif direction not in {"CALL", "PUT"}:
        state, reason = "NO_TRADE", "DIRECTION_NOT_PROVEN"
    elif score is not None and score < MIN_ELIGIBLE_SCORE:
        state, reason = "WATCH", "SCORE_BELOW_70"
    else:
        state, reason = "ELIGIBLE", "SCORE_LOCK_70"

    return {
        **index,
        "spot": spot,
        "direction": direction or None,
        "state": state,
        "reason": reason,
        "score": score,
        "scoreFloor": MIN_ELIGIBLE_SCORE,
        "failedGates": failed,
        "missingInputs": sorted(set(unavailable + missing)),
        "contract": supplied.get("contract"),
        "providerStatus": supplied.get("providerStatus"),
        "dataSource": supplied.get("source"),
        "expiry": supplied.get("expiry"),
        "dataLimitations": supplied.get("dataLimitations") or [],
        "gateEvidence": supplied.get("gateEvidence") or {},
        "chain": supplied.get("rawChain") or [],
        "structure": supplied.get("structure"),
        "oiResearch": supplied.get("oiResearch") or {},
        "componentFreshness": supplied.get("componentFreshness") or {},
        "eligible": eligible,
        "strategyMode": "BUY_PREMIUM",
        "strategyType": "LONG_CALL" if direction == "CALL" else "LONG_PUT" if direction == "PUT" else None,
    }


def _seller_candidate(index: dict[str, str], snapshot: dict[str, Any]) -> dict[str, Any]:
    supplied = ((snapshot.get("indexOptions") or {}).get("indices") or {}).get(index["key"], {})
    seller = supplied.get("seller") if isinstance(supplied.get("seller"), dict) else {}
    components = seller.get("scores") if isinstance(seller.get("scores"), dict) else {}
    required_scores = ("structure", "futuresRegime", "optionChain", "breadth", "volatilityEdge", "contract", "theta")
    weights = {"structure": 15, "futuresRegime": 10, "optionChain": 15, "breadth": 15,
               "volatilityEdge": 15, "contract": 20, "theta": 10}
    missing = [name for name in required_scores if _num(components.get(name)) is None]
    score = None
    if not missing:
        score = round(sum((_num(components[name]) or 0.0) * weights[name] / 100.0 for name in required_scores), 2)
    gates = seller.get("gates") if isinstance(seller.get("gates"), dict) else {}
    required_gates = ("fresh", "structure", "futuresRegime", "optionChain", "breadth", "volatilityEdge",
                      "contractEconomics", "definedRisk", "thetaCarry", "tailBuffer", "timeWindow")
    failed = [name for name in required_gates if gates.get(name) is False]
    unavailable = [name for name in required_gates if gates.get(name) is not True and name not in failed]
    strategy_type = str(seller.get("strategyType") or "")
    bias = str(seller.get("bias") or "").upper()
    construction_status = str(seller.get("constructionStatus") or "")
    eligible = bool(strategy_type and bias in {"BULLISH", "BEARISH", "NEUTRAL"} and not failed and not unavailable
                    and score is not None and score >= SELLER_MIN_SCORE)
    if construction_status:
        state, reason = "NO_TRADE", f"SELLER_CONSTRUCTION_FAILED:{construction_status}"
        failed, unavailable, missing = [], [], []
    elif not seller:
        state, reason = "NO_TRADE", "SELLER_STRUCTURE_UNAVAILABLE"
    elif failed:
        state, reason = "NO_TRADE", f"SELLER_GATE_FAILED:{','.join(failed)}"
    elif unavailable or missing:
        state, reason = "NO_TRADE", f"SELLER_DATA_INCOMPLETE:{','.join(sorted(set(unavailable + missing)))}"
    elif score is not None and score < SELLER_MIN_SCORE:
        state, reason = "WATCH", "SELLER_SCORE_BELOW_FLOOR"
    else:
        state, reason = "ELIGIBLE", "DEFINED_RISK_SELLER_GATES_PASSED"
    primary = seller.get("primaryContract") if isinstance(seller.get("primaryContract"), dict) else None
    return {
        **index,
        "spot": _num(supplied.get("spot")),
        "direction": bias or None,
        "bias": bias or None,
        "state": state,
        "reason": reason,
        "score": score,
        "scoreFloor": SELLER_MIN_SCORE,
        "failedGates": failed,
        "missingInputs": sorted(set(unavailable + missing)),
        "strategyMode": "SELL_PREMIUM",
        "strategyType": strategy_type or None,
        "constructionStatus": construction_status or None,
        "legs": seller.get("legs") or [],
        "risk": seller.get("risk") or {},
        "contract": primary,
        "providerStatus": supplied.get("providerStatus"),
        "dataSource": supplied.get("source"),
        "expiry": supplied.get("expiry"),
        "dataLimitations": seller.get("dataLimitations") or [],
        "gateEvidence": seller.get("gateEvidence") or {},
        "chain": supplied.get("rawChain") or [],
        "structure": supplied.get("structure"),
        "componentFreshness": supplied.get("componentFreshness") or {},
        "eligible": eligible,
    }


def build_index_options_radar(snapshot: dict[str, Any] | None) -> dict[str, Any]:
    payload = snapshot if isinstance(snapshot, dict) else {}
    candidates = [_candidate(index, payload) for index in INDEX_CONFIG]
    seller_candidates = [_seller_candidate(index, payload) for index in INDEX_CONFIG]
    eligible = sorted((row for row in [*candidates, *seller_candidates] if row["eligible"]),
                      key=lambda row: row["score"] or 0, reverse=True)
    selected: list[dict[str, Any]] = []
    used_buckets: set[str] = set()
    used_indexes: set[str] = set()
    for row in eligible:
        if row["bucket"] in used_buckets or row["key"] in used_indexes or len(selected) >= MAX_CONCURRENT_TRADES:
            continue
        selected.append(row)
        used_buckets.add(row["bucket"])
        used_indexes.add(row["key"])
    return {
        "success": True,
        "executionPolicy": "AUTO_PAPER_ONLY",
        "strategy": "LONG_PREMIUM_OR_DEFINED_RISK_PREMIUM_SELLING",
        "updatedAt": payload.get("updatedAt"),
        "candidates": candidates,
        "sellerCandidates": seller_candidates,
        "selected": selected,
        "limits": {
            "minDailyEntries": MIN_DAILY_ENTRIES,
            "maxDailyEntries": MAX_DAILY_ENTRIES,
            "maxConcurrent": MAX_CONCURRENT_TRADES,
            "maxPerCorrelationBucket": 1,
            "scoreFloor": MIN_ELIGIBLE_SCORE,
            "huntMode": "CONTINUOUS_MARKET_SESSION",
        },
        "reentryPolicy": {
            "maxAttemptsPerIndex": MAX_ATTEMPTS_PER_INDEX,
            "hardBanAfterStopLosses": 2,
            "targetCooldownMin": 20,
            "profitTrailCooldownMin": 30,
            "sameDirectionStopCooldownMin": 45,
            "confirmationRequired": ["freshBreakout", "futuresOi", "weightedBreadth"],
            "riskScale": 0.5,
        },
    }

"""Trade outcome tracking for scanner picks.

Persists scanner picks and tracks whether target1/target2/stop-loss is hit
based on live prices. Outcomes are updated each refresh cycle.

State file: trade_api_snapshot.json -> scannerPicks
"""
from __future__ import annotations

import json
import os
import time
import logging
import copy
import threading
from datetime import datetime, timezone, timedelta
from typing import Any

from pathlib import Path
import json as _json

from .exit_plan import attach_exit_plan, evaluate_scale_trail, evaluate_scale_trail_path, exit_plan_is_current, refresh_exit_policy

def _get_market_snapshot() -> dict | None:
    """Load the last market snapshot to get live prices."""
    try:
        from .market_snapshot_store import readable_market_snapshot_path

        with open(readable_market_snapshot_path(), "r", encoding="utf-8-sig") as fh:
            return json.load(fh)
    except Exception:
        return None

log = logging.getLogger(__name__)

_SNAPSHOT_FILE = os.environ.get(
    "SNAPSHOT_FILE",
    os.path.normpath(
        os.path.join(
            os.path.dirname(os.path.abspath(__file__)),
            "..", "..", "..", "trade_api_snapshot.json",
        )
    ),
)
_SESSION_TTL = 6 * 3600  # 6 hours — session expires at EOD
_PRICE_TTL = 120  # seconds before we re-fetch live price

_YAHOO_FINANCE_CACHE: dict[str, tuple[float, float]] = {}
_YAHOO_FINANCE_CACHE_TTL = 30  # seconds

# One computed live-book snapshot is shared by every endpoint and user. Several
# UI panels call this service indirectly; without request coalescing they repeat
# quote fetches, exit evaluation and JSON writes at the same instant.
_LIVE_BOOK_CACHE: dict[str, Any] | None = None
_LIVE_BOOK_CACHE_AT = 0.0
_LIVE_BOOK_CACHE_LOCK = threading.Lock()
_LIVE_BOOK_CACHE_REFRESHING = False
_LIVE_BOOK_CACHE_GEN = 0
_LIVE_BOOK_CACHE_OPEN_TTL = float(os.environ.get("LIVE_BOOK_CACHE_OPEN_TTL", "4"))
_LIVE_BOOK_CACHE_CLOSED_TTL = float(os.environ.get("LIVE_BOOK_CACHE_CLOSED_TTL", "20"))

# NSE equity cash trading session (IST)
_MARKET_OPEN_HOUR = 9
_MARKET_OPEN_MIN = 15
_MARKET_CLOSE_HOUR = 15
_MARKET_CLOSE_MIN = 30
_IST_ZONE = timezone(timedelta(hours=5, minutes=30))


def _ist_now() -> datetime:
    return datetime.now(tz=_IST_ZONE)


def _fetch_yahoo_finance_price(symbol: str) -> float | None:
    """LTP / last print from Yahoo Finance (works session + post-close)."""
    now = time.time()
    cached = _YAHOO_FINANCE_CACHE.get(symbol)
    if cached and (now - cached[1]) < _YAHOO_FINANCE_CACHE_TTL:
        return cached[0]
    try:
        import urllib.request
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}.NS"
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=5) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        meta = data.get("chart", {}).get("result", [{}])[0].get("meta") or {}
        price = meta.get("regularMarketPrice")
        if price is None:
            price = meta.get("postMarketPrice") or meta.get("previousClose")
        if price is not None:
            price = float(price)
            _YAHOO_FINANCE_CACHE[symbol] = (price, now)
            return price
    except Exception:
        pass
    return None


def _fetch_angel_plan_prices(symbols: list[str]) -> dict[str, float]:
    """Fetch fixed-plan marks through bounded Angel batch quote requests."""
    out: dict[str, float] = {}
    if not symbols:
        return out
    try:
        from . import angel_one_feed as aof
    except Exception:
        return out
    client = None
    try:
        client = aof._get_fixed_plan_client()
    except Exception:
        return out
    if client is None:
        return out
    try:
        token_map = aof._load_nse_eq_token_map()
        instruments = aof._symbols_to_instruments(symbols, token_map, client=client)
        for symbol, quote in client.fetch_batch_quotes(instruments).items():
            ltp = float(quote.get("ltp", 0) or quote.get("lastPrice", 0) or 0)
            if ltp > 0:
                out[str(symbol).upper()] = ltp
    except Exception:
        return out
    return out


def fetch_live_marks_for_symbols(symbols: list[str]) -> dict[str, float]:
    """Angel (when session open) + Yahoo fill for arbitrary symbols on trading days.

    Used by plan live-prices and swing-session live MTM so Book/EOD can refresh
    marks without rewriting book_*.json caches.
    """
    unique = list(dict.fromkeys(str(s or "").upper().strip() for s in symbols if s))
    unique = [s for s in unique if s]
    if not unique or not _is_trading_day():
        return {}

    market_open = _is_market_open()
    after_close = _is_after_market_close()
    if not _should_refresh_plan_ltps(market_open, after_close):
        return {}

    out: dict[str, float] = {}
    if market_open:
        out.update(_fetch_angel_plan_prices(unique))

    now = time.time()
    for sym in unique:
        if sym in out:
            continue
        cached = _YAHOO_FINANCE_CACHE.get(sym)
        if cached and (now - cached[1]) < _YAHOO_FINANCE_CACHE_TTL:
            out[sym] = cached[0]
            continue
        price = _fetch_yahoo_finance_price(sym)
        if price is not None:
            out[sym] = price
    return out


def _plan_row_is_open(pos: dict[str, Any]) -> bool:
    """True when the desk still needs a live mark (not closed / not triggered)."""
    if str(pos.get("executionStatus") or "").upper() == "NOT_TRIGGERED":
        return False
    if pos.get("closed"):
        return False
    st = str(pos.get("status") or "").upper()
    if st in ("CLOSED", "STOP LOSS HIT", "TRAIL STOP HIT", "SCALE COMPLETE"):
        return False
    return True


def _should_refresh_plan_ltps(market_open: bool, after_close: bool) -> bool:
    """Refresh open plan tickers on trading days — session open and post-close."""
    if not _is_trading_day():
        return False
    return bool(market_open or after_close)


def _is_trading_day(now: datetime | None = None) -> bool:
    """True if now (IST) falls on a weekday (Mon–Fri)."""
    now = now or _ist_now()
    return now.weekday() < 5


def _is_market_open(now: datetime | None = None) -> bool:
    """True only during the live NSE equity session (Mon–Fri 09:15–15:30 IST)."""
    now = now or _ist_now()
    if not _is_trading_day(now):
        return False
    minutes = now.hour * 60 + now.minute
    open_min = _MARKET_OPEN_HOUR * 60 + _MARKET_OPEN_MIN
    close_min = _MARKET_CLOSE_HOUR * 60 + _MARKET_CLOSE_MIN
    return open_min <= minutes <= close_min


def _is_after_market_close(now: datetime | None = None) -> bool:
    """True once today's NSE session has ended (after 15:30 IST), or non-trading day.

    Pre-open (before 09:15) is *not* after-close — use ``not _is_market_open()`` for
    overnight SESSION CLOSED display so we do not spam Yahoo refresh all night.
    """
    now = now or _ist_now()
    if not _is_trading_day(now):
        return True
    minutes = now.hour * 60 + now.minute
    close_min = _MARKET_CLOSE_HOUR * 60 + _MARKET_CLOSE_MIN
    return minutes > close_min


def _snapshot_path() -> str:
    return _SNAPSHOT_FILE


def _load_snapshot() -> dict[str, Any]:
    try:
        with open(_snapshot_path(), "r", encoding="utf-8-sig") as fh:
            payload = json.load(fh)
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def _atomic_write(path: str, payload: dict[str, Any]) -> None:
    """Write JSON without truncating the live file (Windows Docker safe)."""
    from .json_atomic import atomic_write_json

    atomic_write_json(path, payload)


def _save_snapshot(payload: dict[str, Any]) -> None:
    try:
        _atomic_write(_snapshot_path(), payload)
    except Exception as exc:
        log.warning("Failed to save snapshot: %s", exc)


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _utc_ts() -> int:
    return int(time.time())


def _persist_picks(picks: list[dict[str, Any]], direction: str, scan_ltp: float | None = None) -> None:
    """Persist scan results to snapshot under scannerPicks."""
    snapshot = _load_snapshot()
    picks_map = snapshot.get("scannerPicks") or {}
    now = _utc_ts()

    for p in picks:
        sym = p.get("symbol") or p.get("ticker")
        if not sym:
            continue
        key = f"{sym.upper()}:{direction}"
        existing = picks_map.get(key)

        if existing and existing.get("outcome"):
            picks_map[key] = {**existing, "updatedAt": _utc_now()}
            continue

        entry = {
            "symbol": sym.upper(),
            "name": p.get("name", ""),
            "direction": direction,
            "entryPrice": round(float(p.get("entryPrice") or p.get("buyAbove") or p.get("entry", 0)), 2),
            "stopLoss": round(float(p.get("stopLoss") or 0), 2),
            "target1": round(float(p.get("target1") or 0), 2),
            "target2": round(float(p.get("target2") or 0), 2),
            "riskPerShare": round(float(p.get("riskPerShare") or p.get("risk_per_share") or 0), 2),
            "rrT2": round(float(p.get("rrT2") or 0), 1),
            "approxQty": int(p.get("approxQty") or p.get("approx_qty") or 0),
            "deployedCapital": round(float(p.get("deployedCapital") or p.get("deployed_capital") or 0), 2),
            "riskAmount": round(float(p.get("riskAmount") or p.get("risk_amount") or 0), 2),
            "currentPrice": existing.get("currentPrice") if existing else None,
            "outcome": existing.get("outcome") if existing else None,
            "scanLtp": scan_ltp if scan_ltp is not None else (existing.get("scanLtp") if existing else None),
            "sessionTs": existing.get("sessionTs", now) if existing else now,
            "updatedAt": _utc_now(),
        }
        if existing:
            picks_map[key] = {**existing, **entry, "outcome": existing.get("outcome")}
        else:
            picks_map[key] = entry

    snapshot["scannerPicks"] = picks_map
    snapshot["scannerPicksUpdatedAt"] = _utc_now()
    _save_snapshot(snapshot)


def load_persisted_long_scanner_picks() -> list[dict[str, Any]]:
    """Public accessor: non-expired LONG scanner picks from trade_api_snapshot.json."""
    return [
        p for p in _load_persisted_picks()
        if str(p.get("direction") or "LONG").upper() == "LONG" and p.get("symbol")
    ]


def _load_persisted_picks() -> list[dict[str, Any]]:
    """Load picks from snapshot, archive + prune expired sessions, return flat list.

    Expired picks are archived to eod_archive/{date}.json BEFORE being removed
    from the live snapshot, so EOD reports can still be built from them.
    """
    snapshot = _load_snapshot()
    picks_map = snapshot.get("scannerPicks") or {}
    now = _utc_ts()
    rows: list[dict[str, Any]] = []
    expired: list[str] = []
    for key, p in picks_map.items():
        age = now - int(p.get("sessionTs") or 0)
        if age > _SESSION_TTL:
            expired.append(key)
            continue
        rows.append(p)
    if expired:
        try:
            from .eod_archive import archive_all_expiring
            archive_all_expiring(picks_map, expired, for_date=_ist_now().date())
        except Exception as exc:
            log.warning("Failed to archive expiring picks: %s", exc)
        for key in expired:
            del picks_map[key]
        snapshot["scannerPicks"] = picks_map
        _save_snapshot(snapshot)
    return rows


def _fetch_live_price(ticker: str) -> float | None:
    """Try to get live LTP from market snapshot file."""
    try:
        data = _get_market_snapshot()
        if not data:
            return None
        quotes = data.get("stockQuotes") or {}
        q = quotes.get(ticker.upper())
        if isinstance(q, dict):
            raw = q.get("ltpRaw") or q.get("ltp") or q.get("lastPrice")
            if raw is not None:
                return float(raw)
    except Exception as exc:
        log.debug("Live price fetch failed for %s: %s", ticker, exc)
    return None


def _price_age_ok(pick: dict[str, Any]) -> bool:
    updated = pick.get("updatedAt")
    if not updated:
        return False
    try:
        dt = datetime.fromisoformat(updated)
        age = time.time() - dt.timestamp()
        return age < _PRICE_TTL
    except Exception:
        return False


def _resolve_ltp(pick: dict[str, Any]) -> float:
    """Resolve the best available last traded price for a pick."""
    entry = float(pick.get("entryPrice") or 0)
    raw = pick.get("scanLtp")
    ltp = _fetch_live_price(pick["symbol"])
    if ltp is None and raw is not None:
        try:
            ltp = float(raw)
        except (TypeError, ValueError):
            ltp = None
    if ltp is None:
        ltp = pick.get("currentPrice")
    if ltp is None:
        ltp = entry
    return float(ltp)


def _quote_day_range(symbol: str) -> tuple[float | None, float | None]:
    data = _get_market_snapshot() or {}
    quotes = data.get("stockQuotes") if isinstance(data.get("stockQuotes"), dict) else {}
    sources: list[dict[str, Any]] = []
    q = quotes.get(str(symbol or "").upper())
    if isinstance(q, dict):
        sources.append(q)
    for stock in data.get("stocks") or []:
        if isinstance(stock, dict) and str(stock.get("ticker") or stock.get("symbol") or "").upper() == str(symbol or "").upper():
            sources.append(stock)
            break
    hi = lo = None
    for src in sources:
        if hi is None:
            for key in ("dayHigh", "high", "High"):
                try:
                    val = float(src[key]) if src.get(key) is not None else None
                except (TypeError, ValueError, KeyError):
                    val = None
                if val is not None and val > 0:
                    hi = val
                    break
        if lo is None:
            for key in ("dayLow", "low", "Low"):
                try:
                    val = float(src[key]) if src.get(key) is not None else None
                except (TypeError, ValueError, KeyError):
                    val = None
                if val is not None and val > 0:
                    lo = val
                    break
    return hi, lo


# Session extrema used by the exit engine must start when the modeled trade is
# filled.  A market snapshot's dayHigh/dayLow includes prints before entry and
# therefore cannot prove that this position touched a stop or target.
_POST_ENTRY_PATH_VERSION = "post_entry_live_marks_v1"


def _plausible_live_mark(
    *,
    entry: float,
    risk: float,
    last_mark: float | None,
    new_mark: float,
    direction: str,
) -> bool:
    """Reject one-poll spikes that would fake an initial stop."""
    if new_mark <= 0:
        return False
    ref = last_mark if last_mark is not None and last_mark > 0 else entry
    if ref <= 0:
        return True
    if abs(new_mark - ref) / ref > 0.08:
        return False
    if entry > 0 and risk > 0:
        sign = -1 if str(direction).upper() == "SHORT" else 1
        stop = entry - sign * risk
        through_stop = (
            (str(direction).upper() != "SHORT" and new_mark <= stop)
            or (str(direction).upper() == "SHORT" and new_mark >= stop)
        )
        if through_stop:
            return True
        adverse_r = sign * (ref - new_mark) / risk
        if adverse_r > 1.5:
            return False
    return True


def _evaluate_live_scale_trail(pick: dict[str, Any], ltp: float, *, after_close: bool = False) -> dict[str, Any]:
    """Evaluate only price marks observed after this position was triggered."""
    direction = str(pick.get("direction") or "LONG").upper()
    entry = float(pick.get("entryPrice") or 0)
    risk = float(pick.get("riskPerShare") or 0)
    last_mark = None
    for raw in (pick.get("ltp"), pick.get("currentPrice")):
        try:
            if raw is not None and float(raw) > 0:
                last_mark = float(raw)
                break
        except (TypeError, ValueError):
            continue
    mark = float(ltp)
    if not _plausible_live_mark(
        entry=entry, risk=risk, last_mark=last_mark, new_mark=mark, direction=direction
    ):
        mark = float(last_mark or entry or mark)

    # Legacy sessionHigh/sessionLow values may have been seeded from the full
    # trading-day range.  Trust extrema only when their post-entry provenance
    # is explicit; otherwise begin at the modeled fill and the current mark.
    path_is_post_entry = pick.get("pathEvidenceVersion") == _POST_ENTRY_PATH_VERSION
    prior_high = pick.get("sessionHigh") if path_is_post_entry else None
    prior_low = pick.get("sessionLow") if path_is_post_entry else None
    highs = [v for v in (prior_high, entry, mark) if isinstance(v, (int, float)) and v > 0]
    lows = [v for v in (prior_low, entry, mark) if isinstance(v, (int, float)) and v > 0]
    session_high = max(highs) if highs else None
    session_low = min(lows) if lows else None
    pick["pathEvidenceVersion"] = _POST_ENTRY_PATH_VERSION
    pick["pathEvidenceStartedAt"] = (
        pick.get("pathEvidenceStartedAt") if path_is_post_entry
        else pick.get("triggeredAt") or pick.get("replacedAt") or _utc_now()
    )
    if session_high is not None:
        pick["sessionHigh"] = round(float(session_high), 2)
    if session_low is not None:
        pick["sessionLow"] = round(float(session_low), 2)
    if session_high is not None or session_low is not None:
        return evaluate_scale_trail_path(
            pick, mark, session_high, session_low, after_close=after_close
        )
    return evaluate_scale_trail(pick, mark, after_close=after_close)


def compute_outcome(pick: dict[str, Any]) -> dict[str, Any] | None:
    """Evaluate exits against LTP — scale-trail when exitPlan present, else binary T1/T2/SL."""
    entry = float(pick.get("entryPrice") or 0)
    sl = float(pick.get("stopLoss") or 0)
    t1 = float(pick.get("target1") or 0)
    t2 = float(pick.get("target2") or 0)
    direction = str(pick.get("direction") or "LONG")

    ltp = _resolve_ltp(pick)
    pick["currentPrice"] = ltp
    pick["priceUpdatedAt"] = _utc_now()

    plan = pick.get("exitPlan") if isinstance(pick.get("exitPlan"), dict) else None
    if entry and (sl or pick.get("riskPerShare")) and pick.get("approxQty"):
        if not plan or plan.get("mode") != "SCALE_TRAIL" or not exit_plan_is_current(plan):
            enriched = refresh_exit_policy(pick, keep_exit_state=True)
            pick["exitPlan"] = enriched.get("exitPlan")
            if isinstance(enriched.get("exitState"), dict):
                pick["exitState"] = enriched["exitState"]
            if enriched.get("effectiveStop") is not None:
                pick["effectiveStop"] = enriched["effectiveStop"]
            if enriched.get("target1") is not None:
                pick["target1"] = enriched["target1"]
            if enriched.get("target2") is not None:
                pick["target2"] = enriched["target2"]
            if enriched.get("bookedExitPlan"):
                pick["bookedExitPlan"] = enriched["bookedExitPlan"]
            plan = pick.get("exitPlan")

    if plan and plan.get("mode") == "SCALE_TRAIL":
        result = _evaluate_live_scale_trail(pick, ltp, after_close=False)
        if result:
            if result.get("closed"):
                result["resolvedAt"] = _utc_now()
            if isinstance(result.get("exitState"), dict):
                pick["exitState"] = result["exitState"]
            pick["realizedPnl"] = result.get("realizedPnl")
            pick["unrealizedPnl"] = result.get("unrealizedPnl")
            pick["remainingQty"] = result.get("remainingQty")
            pick["effectiveStop"] = result.get("effectiveStop")
            if result.get("closed"):
                pick["closed"] = True
            return {
                "label": result.get("label"),
                "detail": result.get("detail"),
                "hitLevel": result.get("hitLevel"),
                "ltp": result.get("ltp"),
                "pctChange": result.get("pctChange"),
                "resolvedAt": result.get("resolvedAt"),
                "exitState": result.get("exitState"),
                "realizedPnl": result.get("realizedPnl"),
                "unrealizedPnl": result.get("unrealizedPnl"),
                "remainingQty": result.get("remainingQty"),
                "effectiveStop": result.get("effectiveStop"),
                "rMultiple": result.get("rMultiple"),
                "closed": result.get("closed"),
                "scaleTrail": True,
                "sessionHigh": pick.get("sessionHigh"),
                "sessionLow": pick.get("sessionLow"),
                "pathEvidenceVersion": pick.get("pathEvidenceVersion"),
                "pathEvidenceStartedAt": pick.get("pathEvidenceStartedAt"),
            }

    if not entry or not sl or not t1 or not t2:
        return None

    outcome_label = "PENDING"
    outcome_detail = "Awaiting trade"
    hit_level = None
    pct_change = ((ltp - entry) / entry * 100) if entry else 0.0

    if direction == "LONG":
        if ltp >= t2:
            outcome_label = "TARGET 2 HIT"
            outcome_detail = f"LTP {ltp:.2f} >= T2 {t2:.2f}"
            hit_level = "t2"
        elif ltp >= t1:
            outcome_label = "TARGET 1 HIT"
            outcome_detail = f"LTP {ltp:.2f} >= T1 {t1:.2f}"
            hit_level = "t1"
        elif ltp <= sl:
            outcome_label = "STOP LOSS HIT"
            outcome_detail = f"LTP {ltp:.2f} <= SL {sl:.2f}"
            hit_level = "sl"
        else:
            outcome_label = "PENDING"
            outcome_detail = f"LTP {ltp:.2f} | Entry {entry:.2f} | {pct_change:+.2f}%"
            hit_level = None
    else:
        if ltp <= t2:
            outcome_label = "TARGET 2 HIT"
            outcome_detail = f"LTP {ltp:.2f} <= T2 {t2:.2f}"
            hit_level = "t2"
        elif ltp <= t1:
            outcome_label = "TARGET 1 HIT"
            outcome_detail = f"LTP {ltp:.2f} <= T1 {t1:.2f}"
            hit_level = "t1"
        elif ltp >= sl:
            outcome_label = "STOP LOSS HIT"
            outcome_detail = f"LTP {ltp:.2f} >= SL {sl:.2f}"
            hit_level = "sl"
        else:
            outcome_label = "PENDING"
            outcome_detail = f"LTP {ltp:.2f} | Entry {entry:.2f} | {pct_change:+.2f}%"
            hit_level = None

    return {
        "label": outcome_label,
        "detail": outcome_detail,
        "hitLevel": hit_level,
        "ltp": ltp,
        "pctChange": round(pct_change, 2),
        "resolvedAt": _utc_now() if hit_level else None,
    }


def _finalize_pending_outcome(pick: dict[str, Any], ltp: float) -> dict[str, Any]:
    """Mark a still-PENDING intradAy pick as NOT TRIGGERED at market close."""
    entry = float(pick.get("entryPrice") or 0)
    pct_change = ((ltp - entry) / entry * 100) if entry else 0.0
    return {
        "label": "NOT TRIGGERED",
        "detail": f"LTP {ltp:.2f} | never crossed T1/SL | {pct_change:+.2f}%",
        "hitLevel": None,
        "ltp": ltp,
        "pctChange": round(pct_change, 2),
        "resolvedAt": _utc_now(),
        "final": True,
    }


def evaluate_outcome(pick: dict[str, Any], finalize_if_closed: bool = False) -> dict[str, Any] | None:
    """Compute an outcome, finalizing a still-pending pick if the market has closed."""
    plan = pick.get("exitPlan") if isinstance(pick.get("exitPlan"), dict) else None
    after_close = bool(_is_after_market_close() and finalize_if_closed)

    if plan and plan.get("mode") == "SCALE_TRAIL":
        ltp = _resolve_ltp(pick)
        pick["currentPrice"] = ltp
        existing = pick.get("outcome")
        if existing and existing.get("closed") and existing.get("final"):
            return existing
        result = _evaluate_live_scale_trail(pick, ltp, after_close=after_close)
        if result:
            if result.get("closed"):
                result["resolvedAt"] = _utc_now()
                if after_close:
                    result["final"] = True
            if isinstance(result.get("exitState"), dict):
                pick["exitState"] = result["exitState"]
            return {
                "label": result.get("label"),
                "detail": result.get("detail"),
                "hitLevel": result.get("hitLevel"),
                "ltp": result.get("ltp"),
                "pctChange": result.get("pctChange"),
                "resolvedAt": result.get("resolvedAt"),
                "exitState": result.get("exitState"),
                "realizedPnl": result.get("realizedPnl"),
                "unrealizedPnl": result.get("unrealizedPnl"),
                "remainingQty": result.get("remainingQty"),
                "effectiveStop": result.get("effectiveStop"),
                "rMultiple": result.get("rMultiple"),
                "closed": result.get("closed"),
                "scaleTrail": True,
                "final": result.get("final"),
                "sessionHigh": pick.get("sessionHigh"),
                "sessionLow": pick.get("sessionLow"),
                "pathEvidenceVersion": pick.get("pathEvidenceVersion"),
                "pathEvidenceStartedAt": pick.get("pathEvidenceStartedAt"),
            }

    if not after_close:
        return compute_outcome(pick)

    existing = pick.get("outcome")
    if existing and (existing.get("hitLevel") or existing.get("final")):
        return existing

    ltp = _resolve_ltp(pick)
    pick["currentPrice"] = ltp
    pick["priceUpdatedAt"] = _utc_now()
    pending = compute_outcome(pick)
    if pending and pending.get("hitLevel") is None and not pending.get("scaleTrail"):
        return _finalize_pending_outcome(pick, ltp)
    return pending


def refresh_outcomes() -> None:
    """Re-evaluate all persisted picks and update their outcomes."""
    picks = _load_persisted_picks()
    snapshot = _load_snapshot()
    picks_map = snapshot.get("scannerPicks") or {}
    changed = False
    for p in picks:
        key = f"{p['symbol']}:{p['direction']}"
        entry = picks_map.get(key)
        if not entry:
            continue
        outcome = compute_outcome(entry)
        if outcome and outcome.get("hitLevel"):
            entry["outcome"] = outcome
            changed = True
        elif outcome:
            entry["outcome"] = outcome
            entry["currentPrice"] = outcome["ltp"]
            entry["priceUpdatedAt"] = outcome["resolvedAt"]
            changed = True
    if changed:
        _save_snapshot(snapshot)


