def _load_alert_history() -> list[dict[str, Any]]:
    """Load fired alert history."""
    try:
        with open(_ALERT_HISTORY_FILE, "r", encoding="utf-8-sig") as fh:
            data = json.load(fh)
            if isinstance(data, list):
                return data
    except Exception:
        pass
    return []


def _save_alert_history(history: list[dict[str, Any]]) -> None:
    """Persist alert history (keep last 500)."""
    try:
        trimmed = (history or [])[-500:]
        tmp = _ALERT_HISTORY_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(trimmed, fh, indent=2, default=str)
        os.replace(tmp, _ALERT_HISTORY_FILE)
    except Exception as exc:
        log.warning("Failed to save alert history: %s", exc)


def _record_alert(alert: dict[str, Any]) -> None:
    history = _load_alert_history()
    history.append(alert)
    _save_alert_history(history)


def _alert_already_fired(history: list[dict[str, Any]], key: str, plan_date: str) -> bool:
    return any(a.get("key") == key and a.get("planDate") == plan_date for a in history)


def emit_book_lock_alerts(
    *,
    book: str,
    session_date: str,
    long_rows: list[dict[str, Any]] | None = None,
    short_rows: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    """Persist BUY/SELL pick alerts when a swing or intraday book locks."""
    history = _load_alert_history()
    today = (session_date or _today_ist())[:10]
    new_alerts: list[dict[str, Any]] = []

    def _px(row: dict[str, Any]) -> float | None:
        for k in ("entryPrice", "buyAbove", "ltp", "scanLtp", "currentPrice"):
            raw = row.get(k)
            if raw is None:
                continue
            try:
                return float(raw)
            except (TypeError, ValueError):
                continue
        return None

    def _one(row: dict[str, Any], direction: str) -> None:
        if not isinstance(row, dict):
            return
        sym = str(row.get("symbol") or row.get("ticker") or "").upper().strip()
        if not sym:
            return
        hit = "buy" if direction == "LONG" else "sell"
        action = "BUY" if direction == "LONG" else "SELL"
        key = f"{sym}:{direction}:lock:{book}:{today}"
        if _alert_already_fired(history, key, today):
            return
        px = _px(row)
        alert = {
            "key": key,
            "symbol": sym,
            "direction": direction,
            "hitLevel": hit,
            "label": f"{book} PICK · {action}",
            "ltp": float(px or 0.0),
            "entryPrice": px,
            "planDate": today,
            "firedAt": _utc_now(),
            "book": book,
            "action": action,
        }
        new_alerts.append(alert)
        history.append(alert)

    for r in long_rows or []:
        _one(r, "LONG")
    for r in short_rows or []:
        _one(r, "SHORT")
    for a in new_alerts:
        _record_alert(a)
    return new_alerts


def emit_replacement_alerts(
    *,
    session_date: str,
    rows: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    """Persist BUY/SELL alerts when an intraday free-slot replacement is applied."""
    history = _load_alert_history()
    today = (session_date or _today_ist())[:10]
    new_alerts: list[dict[str, Any]] = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        sym = str(row.get("symbol") or "").upper().strip()
        if not sym:
            continue
        direction = str(row.get("direction") or "LONG").upper()
        hit = "buy" if direction == "LONG" else "sell"
        action = "BUY" if direction == "LONG" else "SELL"
        key = f"{sym}:{direction}:replace:INTRADAY:{today}"
        if _alert_already_fired(history, key, today):
            continue
        try:
            px = float(row.get("entryPrice") or row.get("ltp") or 0)
        except (TypeError, ValueError):
            px = 0.0
        alert = {
            "key": key,
            "symbol": sym,
            "direction": direction,
            "hitLevel": hit,
            "label": f"INTRADAY REPLACE · {action}",
            "ltp": px,
            "entryPrice": px or None,
            "planDate": today,
            "firedAt": _utc_now(),
            "book": "INTRADAY",
            "action": action,
            "replacedFrom": row.get("replacedFrom"),
        }
        new_alerts.append(alert)
        history.append(alert)
    for a in new_alerts:
        _record_alert(a)
    return new_alerts


def collect_hit_alerts_from_rows(
    rows: list[dict[str, Any]],
    *,
    book: str = "INTRADAY",
) -> list[dict[str, Any]]:
    """Fire T1/T2/SL/partial alerts for enriched book rows (deduped by day)."""
    history = _load_alert_history()
    today = _today_ist()
    new_alerts: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        outcome = row.get("outcome") if isinstance(row.get("outcome"), dict) else {}
        hit_level = outcome.get("hitLevel")
        if not hit_level:
            continue
        sym = str(row.get("symbol") or "").upper().strip()
        if not sym:
            continue
        direction = str(row.get("direction") or "LONG").upper()
        if direction not in ("LONG", "SHORT"):
            direction = "LONG"
        key = f"{sym}:{direction}:{hit_level}:{book}"
        if _alert_already_fired(history, key, today):
            continue
        try:
            ltp = float(outcome.get("ltp") if outcome.get("ltp") is not None else row.get("ltp") or 0)
        except (TypeError, ValueError):
            ltp = 0.0
        entry = row.get("entryPrice")
        try:
            entry_f = float(entry) if entry is not None else None
        except (TypeError, ValueError):
            entry_f = None
        hl = str(hit_level).lower()
        if hl == "buy":
            action = "BUY"
        elif hl == "sell":
            action = "SELL"
        else:
            # Targets / SL / partial book — reverse the sleeve side
            action = "SELL" if direction == "LONG" else "BUY"
        alert = {
            "key": key,
            "symbol": sym,
            "direction": direction,
            "hitLevel": hit_level,
            "label": outcome.get("label") or f"{book} · {str(hit_level).upper()}",
            "ltp": ltp,
            "entryPrice": entry_f,
            "planDate": today,
            "firedAt": _utc_now(),
            "book": book,
            "action": action,
        }
        new_alerts.append(alert)
        history.append(alert)
    for a in new_alerts:
        _record_alert(a)
    return new_alerts


def invalidate_live_book_cache() -> None:
    """Drop the coalesced live-book snapshot so disk P&L is not overlaid from stale rows."""
    global _LIVE_BOOK_CACHE, _LIVE_BOOK_CACHE_AT, _LIVE_BOOK_CACHE_GEN
    with _LIVE_BOOK_CACHE_LOCK:
        _LIVE_BOOK_CACHE_GEN += 1
        _LIVE_BOOK_CACHE = None
        _LIVE_BOOK_CACHE_AT = 0.0


def get_live_prices_for_plan() -> dict[str, Any]:
    """Return a process-wide stale-while-refresh live-book snapshot.

    A deep copy protects the cached payload from endpoint-specific enrichment.
    External marks are fetched in a daemon thread so request workers never wait
    on Angel One or Yahoo and cannot pile up behind the cache lock.
    """
    global _LIVE_BOOK_CACHE, _LIVE_BOOK_CACHE_AT, _LIVE_BOOK_CACHE_REFRESHING
    now = time.monotonic()
    ttl = _LIVE_BOOK_CACHE_OPEN_TTL if _is_market_open() else _LIVE_BOOK_CACHE_CLOSED_TTL
    if _LIVE_BOOK_CACHE is not None and now - _LIVE_BOOK_CACHE_AT < ttl:
        return copy.deepcopy(_LIVE_BOOK_CACHE)

    start_refresh = False
    started_gen = 0
    with _LIVE_BOOK_CACHE_LOCK:
        now = time.monotonic()
        ttl = _LIVE_BOOK_CACHE_OPEN_TTL if _is_market_open() else _LIVE_BOOK_CACHE_CLOSED_TTL
        if _LIVE_BOOK_CACHE is not None and now - _LIVE_BOOK_CACHE_AT < ttl:
            return copy.deepcopy(_LIVE_BOOK_CACHE)
        if _LIVE_BOOK_CACHE is None:
            fallback = _compute_live_prices_for_plan(
                allow_external=False,
                persist_transitions=False,
            )
            fallback["dataStale"] = True
            fallback["liveRefreshPending"] = True
            _LIVE_BOOK_CACHE = copy.deepcopy(fallback)
            _LIVE_BOOK_CACHE_AT = 0.0
        if not _LIVE_BOOK_CACHE_REFRESHING:
            _LIVE_BOOK_CACHE_REFRESHING = True
            start_refresh = True
            started_gen = _LIVE_BOOK_CACHE_GEN
        result = copy.deepcopy(_LIVE_BOOK_CACHE)
        result["liveRefreshPending"] = True

    if start_refresh:
        try:
            threading.Thread(
                target=_refresh_live_book_cache,
                args=(started_gen,),
                name="live-book-refresh",
                daemon=True,
            ).start()
        except Exception:
            with _LIVE_BOOK_CACHE_LOCK:
                _LIVE_BOOK_CACHE_REFRESHING = False
            log.exception("failed to start live-book refresh")
    return result


def _refresh_live_book_cache(started_gen: int) -> None:
    """Fetch external marks without occupying an AnyIO request worker."""
    global _LIVE_BOOK_CACHE, _LIVE_BOOK_CACHE_AT, _LIVE_BOOK_CACHE_REFRESHING
    try:
        result = _compute_live_prices_for_plan(allow_external=True)
        result["liveRefreshPending"] = False
        with _LIVE_BOOK_CACHE_LOCK:
            if started_gen != _LIVE_BOOK_CACHE_GEN:
                return
            _LIVE_BOOK_CACHE = copy.deepcopy(result)
            _LIVE_BOOK_CACHE_AT = time.monotonic()
    except Exception:
        log.exception("live-book refresh failed; serving cached marks")
    finally:
        with _LIVE_BOOK_CACHE_LOCK:
            _LIVE_BOOK_CACHE_REFRESHING = False


def _intraday_ws_live_quotes(symbols: list[str]) -> dict[str, dict[str, Any]]:
    """Fresh LTPs from the authoritative in-memory Intraday market state.

    Locked-position MTM reads live WebSocket state first (spec V5 §23/§59);
    REST is only consulted for symbols the stream cannot serve fresh.  STALE
    or UNAVAILABLE quotes are not returned as fresh — the normal REST/
    cached fallback marks them honestly instead of fabricating prices.
    """
    if not symbols:
        return {}
    try:
        from .intraday_market_state import get_intraday_market_state

        snapshot = get_intraday_market_state().capture_snapshot(symbols)
    except Exception:
        logging.getLogger(__name__).debug(
            "Intraday market state unavailable for plan quotes", exc_info=True
        )
        return {}
    out: dict[str, dict[str, Any]] = {}
    for symbol, quote in (snapshot.get("quotes") or {}).items():
        ltp = quote.get("ltp")
        freshness = quote.get("freshness")
        if freshness not in ("LIVE", "DEGRADED"):
            continue
        if ltp is None:
            continue
        out[symbol] = {
            "ltp": float(ltp) if ltp is not None else None,
            "source": quote.get("source"),
            "receivedAt": quote.get("receivedAt"),
            "dataAge": quote.get("dataAge"),
            "freshness": freshness,
        }
    return out


def _compute_live_prices_for_plan(
    *,
    allow_external: bool = True,
    persist_transitions: bool = True,
) -> dict[str, Any]:
    """Return prices + evaluated outcomes for symbols in the fixed plan.

    Honesty contract:
    - Prefer Angel One ltpData / snapshot; Yahoo fills gaps on trading days
      (session open and after 15:30 close marks) for every plan ticker.
    - Never claim tick-live or "no external APIs" — sources are reported per symbol.
    - Cached/entry fallbacks set dataStale=True. Missing price → ltp null, not invented.
    """
    snapshot_prefetch = _get_market_snapshot() or {}
    snapshot_updated_prefetch = snapshot_prefetch.get("updatedAt", "")

    fixed, book_source = load_desk_live_book()
    plan_note = None
    if book_source == "intraday_session":
        plan_note = "Live marks from today's locked Intraday session"
    elif book_source == "none":
        plan_note = "No same-day locked session or plan; Yahoo not attempted"

    if not fixed:
        return {
            "long": [],
            "short": [],
            "updatedAt": _utc_now(),
            "snapshotUpdatedAt": snapshot_updated_prefetch,
            "source": "none",
            "priceSourcesNote": plan_note or "No same-day desk book; Yahoo not attempted",
            "marketOpen": _is_market_open(),
            "sessionClosed": not _is_market_open(),
            "dataStale": True,
            "ltpSourceMix": {"live": 0, "snapshot": 0, "cached": 0, "none": 0, "LOCKED_PRICE_UNAVAILABLE": 0},
        }

    long_plan = fixed.get("long") or []
    short_plan = fixed.get("short") or []
    if not long_plan and not short_plan:
        return {
            "long": [],
            "short": [],
            "updatedAt": _utc_now(),
            "snapshotUpdatedAt": snapshot_updated_prefetch,
            "source": "none",
            "priceSourcesNote": plan_note or "Empty same-day desk book; Yahoo not attempted",
            "marketOpen": _is_market_open(),
            "sessionClosed": not _is_market_open(),
            "dataStale": True,
            "ltpSourceMix": {"live": 0, "snapshot": 0, "cached": 0, "none": 0, "LOCKED_PRICE_UNAVAILABLE": 0},
        }

    open_symbols = list(
        dict.fromkeys(
            str(p.get("symbol") or "").upper()
            for p in (long_plan + short_plan)
            if p.get("symbol") and _plan_row_is_open(p)
        )
    )

    snapshot = snapshot_prefetch
    quotes = snapshot.get("stockQuotes") or {}
    snapshot_updated = snapshot_updated_prefetch

    snapshot_age_sec: int | None = None
    if snapshot_updated:
        try:
            snap_dt = datetime.fromisoformat(str(snapshot_updated).replace("Z", "+00:00"))
            snapshot_age_sec = max(
                0,
                int((datetime.now(tz=timezone.utc) - snap_dt.astimezone(timezone.utc)).total_seconds()),
            )
        except Exception:
            snapshot_age_sec = None

    market_open = _is_market_open()
    after_close = _is_after_market_close()
    plan_changed: list[bool] = []

    alert_history = _load_alert_history()
    new_alerts: list[dict[str, Any]] = []
    source_mix = {"live": 0, "snapshot": 0, "cached": 0, "none": 0}

    # Live marks only for OPEN rows. Closed archive already has exit LTP — Yahoo/Angel
    # on 50+ closed names blocks GET /api/intraday-session past the UI timeout.
    live_quotes: dict[str, float] = {}
    ws_quote_meta: dict[str, dict[str, Any]] = {}
    live_attempted = False
    # Live-market-state first: in-memory WS quotes are the primary authority
    # and need no REST. REST live marks run only for symbols the stream
    # cannot serve fresh (targeted recovery, never a 750-symbol heartbeat).
    for sym, meta in _intraday_ws_live_quotes(open_symbols).items():
        live_quotes[sym] = meta["ltp"]
        ws_quote_meta[sym] = meta
    if allow_external and _should_refresh_plan_ltps(market_open, after_close) and open_symbols:
        live_attempted = True
        if market_open:
            rest_symbols = [sym for sym in open_symbols if sym not in live_quotes]
            angel_quotes = _fetch_angel_plan_prices(rest_symbols)
            live_quotes.update(angel_quotes)
        now = time.time()
        for sym in open_symbols:
            if sym in live_quotes:
                continue
            cached = _YAHOO_FINANCE_CACHE.get(sym)
            if cached and (now - cached[1]) < _YAHOO_FINANCE_CACHE_TTL:
                live_quotes[sym] = cached[0]
                continue
            price = _fetch_yahoo_finance_price(sym)
            if price is not None:
                live_quotes[sym] = price

    def enrich_pick(p: dict[str, Any]) -> dict[str, Any]:
        symbol = (p.get("symbol") or "").upper()
        ltp = None
        ltp_source = "none"
        from_snapshot = False

        if symbol in quotes:
            q = quotes[symbol]
            raw = q.get("ltpRaw") or q.get("ltp") or q.get("lastPrice")
            if raw is not None:
                try:
                    ltp = float(raw)
                    from_snapshot = True
                    ltp_source = "snapshot"
                except (TypeError, ValueError):
                    pass

        # Prefer fresh Angel/Yahoo last print over stale snapshot (incl. after close)
        if symbol in live_quotes:
            ltp = live_quotes[symbol]
            ws_meta = ws_quote_meta.get(symbol)
            if ws_meta is not None:
                if ws_meta.get("freshness") == "LOCKED_PRICE_UNAVAILABLE":
                    ltp_source = "LOCKED_PRICE_UNAVAILABLE"
                else:
                    ltp_source = "ANGEL_WS"
                from_snapshot = False
            else:
                ltp_source = "live"
                from_snapshot = False

        if ltp is None:
            for key in ("scanLtp", "currentPrice", "entryPrice"):
                raw = p.get(key)
                if raw is not None:
                    try:
                        ltp = float(raw)
                        ltp_source = "cached"
                        break
                    except (TypeError, ValueError):
                        pass

        data_stale = ltp_source in ("cached", "none", "LOCKED_PRICE_UNAVAILABLE") or (
            ltp_source == "snapshot"
            and snapshot_age_sec is not None
            and snapshot_age_sec > max(_PRICE_TTL, 300)
        )
        source_mix[ltp_source] = source_mix.get(ltp_source, 0) + 1

        entry: dict[str, Any] = {
            "ltp": round(ltp, 2) if ltp is not None else None,
            "currentPrice": round(ltp, 2) if ltp is not None else None,
            "ltpSource": ltp_source,
            "dataStale": data_stale,
            "priceUpdatedAt": _utc_now(),
        }
        ws_entry = ws_quote_meta.get(symbol)
        if ltp_source == "ANGEL_WS" and ws_entry is not None:
            entry["receivedAt"] = ws_entry.get("receivedAt")
            entry["dataAge"] = ws_entry.get("dataAge")
            # V5 freshness contract: the market-state mix source stays honest
            # ("ANGEL_WS") and stale WS rows are excluded upstream, so the WS
            # mark here is fresh.

        if ltp is None:
            entry["outcome"] = None
            entry["status"] = "DATA STALE"
            return {**p, **entry}

        execution_status = str(p.get("executionStatus") or "").upper()
        if execution_status in {"PENDING_ENTRY", "NOT_TRIGGERED"} or p.get("triggered") is False:
            entry.update({
                "outcome": None,
                "closed": False,
                "realizedPnl": 0.0,
                "unrealizedPnl": 0.0,
                "remainingQty": 0,
                "status": "PENDING ENTRY" if execution_status == "PENDING_ENTRY" else "NOT_TRIGGERED",
                "executionStatus": execution_status or "PENDING_ENTRY",
            })
            return {**p, **entry}

        # CLOSED positions stay CLOSED — do not re-open via price refresh
        if p.get("closed") or str(p.get("status") or "").upper() == "CLOSED":
            entry["status"] = "CLOSED"
            entry["closed"] = True
            entry["outcome"] = p.get("outcome")
            return {**p, **entry}


